"use client";

import { useEffect, useRef, useState } from "react";
import { contentClient } from "../../../../../lib/sdk";
import type { ArtifactListItem } from "../sources-hub/types";
import { isArtifactPending } from "./utils";

/**
 * Artifacts generated by a background job outside the chat stream (a table or
 * study set started from the source hub, or one reopened while it runs) report progress
 * only in their stored record. While the preview shows one that is still
 * running, the panel re-reads the record through the ordinary detail call
 * until it finishes.
 *
 * Keyed by artifact type; the predicate says whether a record is still
 * running. Another background-generated type adds its entry here.
 */

/**
 * Pending or running, or a ready artifact whose next version is being
 * generated (`payload_json.<namespace>.regeneration.status`, which the job
 * replaces when the version publishes and marks failed when it does not).
 */
function pendingOrRegenerating(namespace: string) {
  return (artifact: ArtifactListItem) => {
    if (isArtifactPending(artifact)) return true;
    const payload = artifact.payloadJson as Record<string, unknown> | null | undefined;
    const state = payload?.[namespace] as { regeneration?: { status?: unknown } } | undefined;
    return state?.regeneration?.status === "running";
  };
}

const studyRunning = pendingOrRegenerating("study");

export const ARTIFACT_LIVE_REFRESH: Readonly<
  Record<string, (artifact: ArtifactListItem) => boolean>
> = {
  table: isArtifactPending,
  flashcards: studyRunning,
  quiz: studyRunning,
  mindmap: studyRunning,
};

const refreshListeners = new Map<string, Set<() => void>>();

/**
 * Asks an open preview of this artifact to re-read it now (a regeneration was
 * just queued); from there it keeps refreshing while the record says it runs.
 */
export function refreshLiveArtifact(artifactId: string) {
  for (const listener of refreshListeners.get(artifactId) ?? []) listener();
}

function onRefreshRequest(artifactId: string, listener: () => void) {
  const listeners = refreshListeners.get(artifactId) ?? new Set<() => void>();
  listeners.add(listener);
  refreshListeners.set(artifactId, listeners);
  return () => {
    listeners.delete(listener);
    if (listeners.size === 0) refreshListeners.delete(artifactId);
  };
}

export const LIVE_REFRESH_INTERVAL_MS = 3_000;
/** A generation still running after this long is left alone; reopening starts again. */
export const LIVE_REFRESH_MAX_DURATION_MS = 15 * 60_000;
/** Consecutive failed reads after which the panel keeps what it has. */
export const LIVE_REFRESH_MAX_FAILURES = 3;

function stillRunning(artifact: ArtifactListItem) {
  return ARTIFACT_LIVE_REFRESH[artifact.artifactType]?.(artifact) ?? false;
}

function timeOf(value: unknown) {
  const time = new Date(value as string).getTime();
  return Number.isNaN(time) ? 0 : time;
}

function sameRecord(a: ArtifactListItem, b: ArtifactListItem) {
  return (
    a.id === b.id &&
    timeOf(a.updatedAt) === timeOf(b.updatedAt) &&
    a.status === b.status &&
    a.artifactVersionId === b.artifactVersionId &&
    JSON.stringify(a.payloadJson) === JSON.stringify(b.payloadJson)
  );
}

/**
 * The artifact to show: the one passed in, or a fresher read of it while it
 * runs. Whichever record was updated later wins, so a parent that already
 * receives updates (the chat stream) is never overruled by an older read, and
 * an identical read changes nothing.
 */
export function useLiveArtifact(
  artifact: ArtifactListItem,
  workspaceId: string | null | undefined,
): ArtifactListItem {
  const [polled, setPolled] = useState<ArtifactListItem | null>(null);
  const shown =
    polled &&
    polled.id === artifact.id &&
    timeOf(polled.updatedAt) > timeOf(artifact.updatedAt)
      ? polled
      : artifact;
  const running = stillRunning(shown);
  const artifactId = artifact.id;
  const [refreshRequests, setRefreshRequests] = useState(0);
  const handledRefreshRequests = useRef(0);

  useEffect(
    () => onRefreshRequest(artifactId, () => setRefreshRequests((count) => count + 1)),
    [artifactId],
  );

  useEffect(() => {
    const requested = refreshRequests !== handledRefreshRequests.current;
    handledRefreshRequests.current = refreshRequests;
    if ((!running && !requested) || !workspaceId) return;
    let cancelled = false;
    let timer: ReturnType<typeof setTimeout> | undefined;
    let failures = 0;
    const startedAt = Date.now();

    const schedule = () => {
      if (Date.now() - startedAt + LIVE_REFRESH_INTERVAL_MS > LIVE_REFRESH_MAX_DURATION_MS) {
        return;
      }
      timer = setTimeout(() => void poll(), LIVE_REFRESH_INTERVAL_MS);
    };

    const poll = async () => {
      try {
        const { artifact: fresh } = await contentClient.getArtifact(workspaceId, artifactId);
        if (cancelled) return;
        failures = 0;
        if (fresh.id !== artifactId) return;
        setPolled((current) => (current && sameRecord(current, fresh) ? current : fresh));
        if (!stillRunning(fresh)) return;
      } catch {
        if (cancelled) return;
        failures += 1;
        // The last state stays on screen; reopening the artifact tries again.
        if (failures >= LIVE_REFRESH_MAX_FAILURES) return;
      }
      schedule();
    };

    // A request is answered at once; a running record is re-read on a timer.
    if (requested) void poll();
    else schedule();
    return () => {
      cancelled = true;
      clearTimeout(timer);
    };
  }, [running, workspaceId, artifactId, refreshRequests]);

  return shown;
}
